<script lang="ts">
  import {onMount} from 'svelte';import type {Field} from '#lib/client/types.ts';import Icon from './Icon.svelte';
  let {value=$bindable(),kind='customers',targetFields}:{value?:string;kind?:string;targetFields?:Field[]}=$props();let rows:{id:string;source:string;target:string}[]=$state([]);let error=$state('');
  const fields=$derived(targetFields?.length?[...targetFields.map(field=>({key:field.key,name:field.label})),...(targetFields.some(field=>field.key==='legacy_id')?[]:[{key:'legacy_id',name:'Eindeutige Alt-ID'}])]:kind==='bank'?[{key:'booking_date',name:'Buchungstag'},{key:'value_date',name:'Wertstellung'},{key:'amount',name:'Betrag mit Vorzeichen'},{key:'currency',name:'Währung'},{key:'reference',name:'Verwendungszweck'},{key:'counterparty',name:'Gegenpartei'},{key:'counterparty_iban',name:'IBAN der Gegenpartei'},{key:'external_id',name:'Eindeutige Bankreferenz'}]:kind==='prices'?[{key:'sku',name:'Lieferantenartikelnummer'},{key:'product_id',name:'Geprüfte Produkt-ID'},{key:'name',name:'Bezeichnung'},{key:'amount',name:'Preis'},{key:'basis_quantity',name:'Preisbasismenge'},{key:'unit',name:'Preiseinheit'},{key:'currency',name:'Währung'}]:kind==='products'?[{key:'name',name:'Bezeichnung'},{key:'sku',name:'Artikelnummer'},{key:'unit',name:'Einheit'},{key:'description',name:'Beschreibung'},{key:'kind',name:'Produktart'}]:[{key:'name',name:'Name / Firma'},{key:'number',name:'Vorhandene Kundennummer'},{key:'email',name:'E-Mail'},{key:'phone',name:'Telefon'},{key:'street',name:'Straße und Hausnummer'},{key:'postal_code',name:'Postleitzahl'},{key:'city',name:'Ort'},{key:'country',name:'Ländercode'},{key:'legacy_id',name:'Eindeutige Alt-ID'}]);
  onMount(()=>{try{const mapping=JSON.parse(value||'{}');if(mapping&&typeof mapping==='object'&&!Array.isArray(mapping))rows=Object.entries(mapping).map(([source,target])=>({id:crypto.randomUUID(),source,target:String(target)}));}catch{error='Das bisherige Mapping ist noch nicht lesbar. Prüfen Sie die vorhandene Zuordnung.';}});
  function change(){error='';const duplicates=rows.filter(r=>r.source&&rows.filter(x=>x.source===r.source).length>1);for(const row of rows){const input=document.getElementById(`mapping-source-${row.id}`) as HTMLInputElement|null;input?.setCustomValidity(duplicates.some(r=>r.id===row.id)?'Jede Quellspalte darf nur einmal zugeordnet sein.':'');}if(duplicates.length){error='Ein Spaltenname ist mehrfach zugeordnet. Bitte jede Quellspalte nur einmal auswählen.';return;}value=JSON.stringify(Object.fromEntries(rows.filter(r=>r.source&&r.target).map(r=>[r.source,r.target])));}
  function add(){rows=[...rows,{id:crypto.randomUUID(),source:'',target:''}];}
  function remove(id:string){rows=rows.filter(r=>r.id!==id);change();}
</script>
<div class="mapping-editor"><p class="field-help">Ordnen Sie die Spalten aus Ihrer Datei den passenden Angaben zu. Noch unklare Zuordnungen bleiben im anschließenden Prüfkorb sichtbar.</p>{#each rows as row,index}<div class="mapping-row"><div class="field"><label for={`mapping-source-${row.id}`}>Spalte aus der Datei *</label><input id={`mapping-source-${row.id}`} value={row.source} oninput={e=>{row.source=e.currentTarget.value;change();}} placeholder={kind==='bank'?'Zum Beispiel Buchungstag':'Zum Beispiel Kundenname'} required/></div><Icon name="arrow" size={16}/><div class="field"><label for={`mapping-target-${row.id}`}>In Schubert übernehmen als *</label><select id={`mapping-target-${row.id}`} value={row.target} onchange={e=>{row.target=e.currentTarget.value;change();}} required><option value="">Passende Angabe auswählen</option>{#each fields as field}<option value={field.key}>{field.name}</option>{/each}</select></div><button class="icon-button" type="button" aria-label={`Spaltenzuordnung ${index+1} entfernen`} onclick={()=>remove(row.id)}><Icon name="trash" size={17}/></button></div>{/each}{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}<button class="btn mt" type="button" onclick={add}><Icon name="plus" size={15}/>Spalte zuordnen</button>{#if !rows.length}<p class="field-help mt">Sie können die Datei auch zunächst ohne Zuordnung analysieren lassen. Es werden dadurch noch keine Geschäftsdaten übernommen.</p>{/if}<details class="mt"><summary class="field-help" style="cursor:pointer">Technische Zuordnung ansehen</summary><pre class="json-preview mt">{value}</pre></details></div>
<style>.mapping-row{display:grid;grid-template-columns:1fr 20px 1fr 35px;align-items:end;gap:12px;margin-top:18px}.mapping-row>:global(svg){align-self:center;margin-top:23px}.mapping-editor>.field-help{max-width:68ch}@media(max-width:760px){.mapping-row{grid-template-columns:1fr 38px;gap:12px;border-top:1px solid var(--line);padding-top:18px}.mapping-row>:global(svg){display:none}.mapping-row .field{grid-column:1}.mapping-row .icon-button{grid-column:2;grid-row:1/3}.mapping-row input,.mapping-row select{font-size:16px}}</style>
